// Replyze signs only the raw body: X-Replyze-Signature is "sha256=" and the hex
// HMAC-SHA256 of the exact bytes received, keyed with this webhook's signing
// secret. "Sign the raw body" computed that HMAC over the same bytes.
// X-Replyze-Timestamp and X-Replyze-Event-Id are unsigned copies of the body's
// created_at and id: anyone who captured a request can send it again with new
// values in them. So this node reads the time and the id from the signed body.
const MAX_AGE_SECONDS = 300;

const item = $input.first().json;
const answer = (status, handle, response, extra = {}) => [{ json: { status, handle, response, ...extra } }];

// 1. The signature, compared as bytes and in constant time: every byte of the
//    expected value is checked, whatever the first difference.
const bytes = (text) => new TextEncoder().encode(text);
const expected = bytes('sha256=' + item.expectedSignature);
const header = (item.headers || {})['x-replyze-signature'];
const given = typeof header === 'string' ? bytes(header) : new Uint8Array(0);
let difference = expected.length ^ given.length;
for (let i = 0; i < expected.length; i++) {
  difference |= expected[i] ^ (i < given.length ? given[i] : 0);
}
if (difference !== 0) {
  return answer(401, false, { error: 'The signature does not match.' });
}

// 2. Signed, so the body can be trusted: parse the exact bytes that were
//    signed ("Raw body") and take the time from them.
let event = null;
try {
  event = JSON.parse(item.rawBody);
} catch (error) {
  event = null;
}
const now = Date.now();
const sentAt = event && typeof event.created_at === 'string' ? Date.parse(event.created_at) : NaN;
if (!Number.isFinite(sentAt) || Math.abs(now - sentAt) > MAX_AGE_SECONDS * 1000) {
  return answer(400, false, { error: 'Too old: the event was not created in the last ' + MAX_AGE_SECONDS + ' seconds.' });
}

// 3. The id, from the body too. An event this workflow has already taken
//    (Replyze's retry, or a replay) gets 200 and goes no further. The ids are
//    kept in the workflow's static data for as long as step 2 would let the
//    event in. n8n saves static data when a run of the published workflow ends.
const id = typeof event.id === 'string' ? event.id : '';
if (id === '') {
  return answer(400, false, { error: 'The event has no id.' });
}
const memory = $getWorkflowStaticData('global');
const seen = {};
for (const [key, until] of Object.entries(memory.replyzeEventIds || {})) {
  if (until >= now) seen[key] = until;
}
if (Object.prototype.hasOwnProperty.call(seen, id)) {
  return answer(200, false, { received: true, duplicate: true }, { eventId: id });
}
seen[id] = sentAt + MAX_AGE_SECONDS * 1000;
memory.replyzeEventIds = seen;

return answer(200, true, { received: true }, { eventId: id, body: event });

// conversation.created: the conversation's first message from the visitor or
// the team. Its payload has no message text, so "Get the first messages" read it.
const conversation = $('Handle it?').first().json.body.data.conversation;
const messages = ($input.first().json.data || []).filter((m) => !m.is_internal_note && m.sender_type !== 'system');
const first = messages.find((m) => m.sender_type === 'visitor' || m.sender_type === 'agent');

// A conversation your team started (from the inbox or the API) is no news to your team.
const startedByVisitor = Boolean(first && first.sender_type === 'visitor');

const contact = conversation.contact || {};
const who = contact.name || contact.email || contact.phone || 'A visitor';
const channels = { web: 'website chat', email: 'email', whatsapp: 'WhatsApp', telegram: 'Telegram', facebook: 'Messenger', messenger: 'Messenger', instagram: 'Instagram' };
const channel = channels[conversation.channel] || conversation.channel;
const words = first && first.content ? first.content.trim() : '(no text: a file or an image)';
const quote = (words.length > 500 ? words.slice(0, 500) + '…' : words).split('\n').map((line) => '> ' + line).join('\n');

return [{
  json: {
    startedByVisitor,
    text: '*New ' + channel + ' conversation* from ' + who + '\n' + quote + '\n<' + conversation.url + '|Open it in Replyze>',
  },
}];
